class CQuadWorkspace:
    def __init__(self, workspace_size):
        self.workspace_size = workspace_size
        self.workspace = ctypes.create_string_buffer(workspace_size)

    def get_workspace_ptr(self):
        return ctypes.cast(ctypes.pointer(self.workspace), ctypes.POINTER(ctypes.c_void_p))

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    gsl_integration_cquad = gsl.gsl_integration_cquad

