import ctypes
import os

def load_gsl_libraries():
    gslcblas = ctypes.CDLL(os.path.join('/usr/local/gsl/lib', 'libgslcblas.so'), mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL(os.path.join('/usr/local/gsl/lib', 'libgsl.so'))
    return (gslcblas, gsl)

def gsl_strerror(errno):
    (gslcblas, gsl) = load_gsl_libraries()
    gsl_strerror = gsl.gsl_strerror
    return ctypes.cast(gsl_strerror, ctypes.c_char_p).value.decode('utf-8')

def main():
    test_cases = [
        (0, 'No error'),
        (1, 'Error 1'),
        (2, 'Error 2'),
        (3, 'Error 3'),
    ]
    for errno, expected in test_cases:
        actual = gsl_strerror(errno)
        assert actual == expected

