def inverse_cdf_tdist(P, nu):
    # Check if P is 0 or 1, and return the corresponding t-value
    if P == 0:
        return -ctypes.c_double(nu) / 2
    elif P == 1:
        return ctypes.c_double(nu) / 2

    # Check if nu is 1 or 2, and return the corresponding t-value
    if nu == 1:
        return -ctypes.c_double(1) / sqrt(P * (1 - P))
    elif nu == 2:
        return ctypes.c_double(1) / sqrt(P * (1 - P))

    # Otherwise, compute the inverse CDF using GSL
    return gsl_cdf_tdist_Pinv(P, nu)

