def numpy_to_gsl_matrix(np_array):
    matrix = gsl.gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            matrix = gsl.gsl_matrix_set(matrix, i, j, np_array[i][j])
    return matrix

def gsl_matrix_to_numpy(gsl_matrix):
    np_array = []
    for i in range(gsl_matrix.rows()):
        row = []
        for j in range(gsl_matrix.cols()):
            row.append(gsl_matrix.get(i, j))
        np_array.append(row)
    return np.array(np_array)

def compute_covariance_matrix(jacobian, epsrel, dims):
