def add_matrices(matrix_a, matrix_b):
    rows = matrix_a.get_rows()
    cols = matrix_a.get_cols()
    if rows != matrix_b.get_rows() or cols != matrix_b.get_cols():
        raise ValueError("Matrices must have the same dimensions")
    result = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
