        return sum(a * b for a, b in zip(self.data, other))

    def __rmul__(self, other):
        return self.__mul__(other)

    def norm(self):
        return sqrt(sum(x ** 2 for x in self.data))

class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.nrows = len(data)
        self.ncols = len(data[0]) if data else 0

