class gsl_matrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))()
        self.size = rows * cols

    def to_gsl(self):
        return gsl.gsl_matrix_alloc(self.rows, self.cols)

class gsl_vector:
    def __init__(self, size):
        self.size = size
        self.data = (ctypes.c_double * size)()

    def to_gsl(self):
        return gsl.gsl_vector_alloc(self.size)

def matrix_to_gsl(matrix):
    rows, cols = len(matrix), len(matrix[0])
    mat = gsl_matrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            mat.data[i * cols + j] = matrix[i][j]
    return mat.to_gsl()

def vector_to_gsl(vector):
    vec = gsl_vector(len(vector))
    for i, v in enumerate(vector):
        vec.data[i] = v
    return vec.to_gsl()

def ql_decomposition_and_unpack(A, tau):
    A = matrix_to_gsl(A)
    tau = vector_to_gsl(tau)
    Q = gsl_matrix(A.rows, A.cols)
    L = gsl_matrix(A.rows, A.cols)
    gsl.gsl_linalg_QL_decomp(A, Q, tau)
    gsl.gsl_linalg_QL_unpack(Q, L, tau)
    return [gsl_matrix_to_list(Q), gsl_matrix_to_list(L)]

def gsl_matrix_to_list(mat):
    rows, cols = mat.rows, mat.cols
    result = []
    for i in range(rows):
        row = []
        for j in range(cols):
            row.append(mat.data[i * cols + j])
        result.append(row)
    return result

