import numpy as np

gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

def compute_incomplete_beta(a, b, x):
    gsl_sf_beta_inc = gsl.gsl_sf_beta_inc
    gsl_sf_beta_inc.restype = ctypes.c_double
    gsl_sf_beta_inc.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double]
    return gsl_sf_beta_inc(a, b, x)

