    # Test case 1:
    assert np.isclose(compute_incomplete_beta(0.5, 2.0, 0.7), 0.864935959180896)
    # Test case 2:
    assert np.isclose(compute_incomplete_beta(2.0, 3.0, 0.7), 0.761237979784862)

